"""r44 内容块 3：female.tex 与 male.tex 薄条增写"""
C = {}

# ---------- female.tex ----------
C["f1057"] = r"""月经贫困的影响远超"买不起卫生巾"本身：买不起或买不到用品的女性可能被迫使用旧布、报纸甚至纸壳替代，由此引发的生殖道感染风险显著上升；经期缺课、缺勤则固化为教育与就业机会的流失，形成"贫困——经期失学——更贫困"的循环。国际上的应对措施包括：苏格兰 2020 年通过立法成为首个免费供应经期用品的地区，多国陆续取消卫生用品进口关税、开展校园与偏远地区免费发放项目。对个人而言，选择适合自身流量的用品（护垫、卫生巾、月经杯等）、了解经血量过多的就医标准（如两小时浸透一片日用卫生巾），既是对健康的保护，也是对议题最直接的参与。"""

C["f11351"] = r"""了解生育生理是避孕决策的前提：月经周期中，排卵通常发生在下次月经来潮前约 14 天，卵子排出后可受精的窗口仅约 24 小时，而精子在女性生殖道内可存活最长 5 天——这正是"排卵前后几天最易受孕"的原理，也是安全期避孕失败率高（排卵时间会波动）的原因。备孕方面，孕前 3 个月开始每日补充 0.4--0.8 毫克叶酸可显著降低胎儿神经管缺陷风险；慢性病、长期服药或有不良孕产史者建议先行孕前咨询。无论打算避孕还是备孕，把月经周期记录下来（日期、天数、伴随症状）都是给医生和自己最有用的第一手资料。"""

C["f13930"] = r"""更年期管理的要点是"分层应对"。对轻度症状，生活方式调整常常已足够：规律运动（尤其负重运动与力量训练，有助于维持骨密度）、控制体重、减少酒精与咖啡因、保持社交与睡眠。中重度血管舒缩症状（潮热、盗汗、情绪波动）可考虑绝经激素治疗（MHT），它仍是目前最有效的手段，但须由医生评估适应证与禁忌证（如乳腺癌、血栓病史），并定期随诊；不愿或不能用激素者，也有非激素药物与盆底、认知行为治疗等选择。此外，绝经后骨量流失加速，建议评估骨密度；持续存在的阴道干涩、性交痛并非"忍忍就过"，局部雌激素或润滑剂可显著改善。每年一次妇科与乳腺检查应坚持到绝经之后。"""

C["f14438"] = r"""女性性生活的舒适与安全，有几个贯穿一生的要点。其一是润滑：阴道干涩不仅出现在绝经后，哺乳期、压力大、服用某些药物时都很常见，水基润滑剂没有激素、可日常使用，不必视为"问题"。其二是盆底健康：产后与围绝经期做凯格尔训练，既改善控尿也有助于性感受。其三是清洁的度：外阴用清水清洗即可，阴道有自净能力，反复冲洗反而破坏菌群。其四是防护：绝经前无生育需求仍有怀孕可能，避孕措施应坚持到确认绝经；更换性伴侣时，避孕套仍然必要。最后是定期妇科检查，把宫颈筛查、乳腺检查列入自己的年度日程，而不是"不舒服才去"。"""

C["f15586"] = r"""就诊时机的选择直接影响检查质量与舒适度：常规妇科检查宜在月经干净后 3--7 天进行，避免经期（异常出血的诊治除外）；检查前 1--2 天避免性生活、阴道冲洗与上药，以免影响分泌物检验结果。常见项目包括：妇科双合诊、白带常规、宫颈细胞学检查（TCT）与 HPV 检测（一般 21 岁起或性生活开始后 3 年内启动，联合筛查阴性者间隔可延长至 5 年）、妇科超声（了解子宫与卵巢）、乳腺检查。需要强调两点：接种过 HPV 疫苗仍须定期筛查，因为疫苗不覆盖所有高危型别；检查中任何环节感到疼痛或紧张，都有权要求暂停、更换体位或请女性医护协助，不必勉强忍让。"""

C["f20662"] = r"""中医对女性性健康的贡献主要体现在经期与围产期的调养观念上："经期忌寒凉、慎劳累"与现代医学"经期注意保暖与休息"不谋而合；"产后多虚多瘀"提示产后贫血与恢复期需要营养与休息的支持。常用方剂如四物汤、逍遥散等多围绕"养血、疏肝"展开，对应现代所说的贫血改善与情绪调节。需要提醒的是：中药同样有适应证与禁忌，阴道不规则出血、异常分泌物等症状应先做妇科检查排除器质性疾病，切勿自行长期服药而延误诊治；所谓"调理"应在正规中医师辨证指导下进行。把中医调养视为生活方式的补充，与现代妇科诊疗互为配合，是更稳妥的态度。"""

# ---------- male.tex ----------
C["m1325"] = r"""男性性欲节律最直观的表现之一是晨勃——它与憋尿反射和快速眼动睡眠期的激素波动有关，是血管与神经功能完好的信号，而与"当天想做爱"没有必然联系。年龄带来的频率下降也属正常：30 岁后睾酮每年约下降 1\%，多数人的性欲峰值在青年期，此后进入平缓期，规律的性生活本身有助于维持功能。
真正需要留意的是"断崖式"变化：性欲在数周至数月内明显下滑，或伴随疲劳、情绪低落、晨勃消失，可能与睾酮低下、睡眠呼吸暂停、抑郁、糖尿病或药物（部分降压药、抗抑郁药）有关，建议就诊查因，而不是自行服用所谓"壮阳"保健品——后者掩盖症状、延误诊断的风险远大于收益。"""

C["m1526"] = r"""精液分析是男性生育力评估的基石，判读依据世界卫生组织第 6 版参考值（如精子浓度 1600 万/毫升、前向运动率 30\% 等）。需要强调：单次结果波动很大，发热、熬夜、禁欲时间不当都会明显影响读数，异常者通常需间隔 2--3 周复查 2--3 次再下结论；"低于参考值"也不等于不能生育，只是提示需要进一步检查。病因上，精索静脉曲张、梗阻、激素异常、染色体因素各占一定比例，处理路径完全不同——从手术矫正到辅助生殖都有相应选项。同时别忘了：约一半的不育夫妇存在男方因素，夫妇同查同诊，才是对的起点。"""

C["m1744"] = r"""目前最接近临床应用的方向有三类：一是激素类方法——每日于肩部涂抹的睾酮--孕激素复方凝胶（如 Nestorone/睾酮凝胶）已完成 II 期试验，通过抑制脑垂体信号使精子发生降至避孕水平，且不依赖注射；二是非激素类——印度研发的可逆性输精管内凝胶（RISUG）已在印度进入后期审批，向输精管内注射一次即可阻断精子通路，理论上可冲洗逆转；三是靶向精子成熟或输送的小分子药物，多处于临床前阶段。共同的技术挑战在于"可逆性验证"与"起效/恢复所需时间"，以及男性避孕意愿与责任分担的社会观念变化——后者往往比技术本身更决定这些方法能否普及。"""

C["m3796"] = r"""生活方式因素里，戒烟的获益时间线最能说明问题：停止吸烟 24 小时内一氧化碳水平回落，数周后血管内皮功能开始改善，轻中度 ED 患者在戒烟数月后勃起质量的提升在多项研究中得到证实。运动方面，每周 150 分钟中等强度有氧加 2 次力量训练，对勃起功能、睾酮水平与精子质量的改善均有证据支持；久坐（尤其长时间骑行压迫会阴）则可能起反作用。饮食上，地中海式饮食模式与较好的勃起功能相关联。睡眠与压力管理的意义同样不该低估——它们通过皮质醇与睾酮的平衡直接影响欲望与表现。可以把这一节看作"男科的体检处方"：多数改变不需要医生处方，需要的只是开始。"""

C["m5057"] = r"""男性骨质疏松的危险因素包括：长期睾酮低下、过量饮酒、吸烟、糖皮质激素长期使用、慢性肝病与吸收不良疾病。建议以下人群做骨密度（DXA）检查：70 岁以上男性常规筛查；65--70 岁伴上述危险因素者；任何年龄出现低创伤性骨折（如从站立高度摔倒即骨折）者。防治策略上，负重运动、补充维生素 D 与足量钙摄入是基础；确诊睾酮缺乏者，在医生评估下补充睾酮可同时改善骨密度，但治疗前必须筛查前列腺并定期监测 PSA，前列腺癌患者属相对禁忌。骨折一旦发生，男性髋部骨折的死亡率高于女性，这正是"别把骨质疏松当女性专属病"的核心理由。"""

C["m7656"] = r"""对男性而言，四期反应有几个与女性不同的特点：兴奋期与平台期的分界不如女性明显，勃起一旦确立常持续整个反应周期；高潮期射精由精液在尿道前列腺部的"汇集感"触发，此后迅速进入\textbf{不应期}——即无论何种刺激都难以再次勃起的时间窗。不应期长短个体差异极大，从青年期的数分钟到老年期的数小时甚至数日都属正常范围，且随年龄延长，不必以此衡量"能力"。
此外，全身性反应值得了解：性唤起时心率、血压上升，肌肉张力普遍增高，高潮瞬间甚至出现短暂的呼吸节律紊乱——这也是严重心血管疾病患者需要医生评估性生活安全性的原因。理解自己的反应周期，还有助于识别异常：持续数月的勃起不坚、高潮时疼痛或射精量骤减，都值得就诊而非自行归因于"最近太累"。"""

C["m7684"] = r"""中医"肾主生殖"的理论把男性生育力、性功能与整体精气状态联系起来，其价值在于提醒人们：性功能是全身健康的"晴雨表"，熬夜、过劳、久坐、情绪郁结都会反映到性上来。"节制房事、养精蓄锐"的传统观念若剥离神秘色彩，可以理解为对体力分配与频率个体化的朴素建议——以事后不觉疲劳、不影响次日状态为度。中药如淫羊藿、人参等成分改善性功能的现代研究有一定进展，但市面"补肾壮阳"产品鱼龙混杂，掺入西药成分的案例并不少见。稳妥的做法仍是：先到正规医院男科查清病因（血管、激素、心理各占不同比重），再决定是否辅以中医调理，并坚持在正规中医机构就诊。"""

